import 'dart:io';import 'package:flutter/material.dart';import 'package:image_picker/image_picker.dart';class PhotoPicker extends StatefulWidget{const PhotoPicker({super.key,required this.onChanged});final ValueChanged<File?> onChanged;@override State<PhotoPicker> createState()=>_PhotoPickerState();}class _PhotoPickerState extends State<PhotoPicker>{File? file;Future<void> pick()async{final x=await ImagePicker().pickImage(source:ImageSource.gallery,imageQuality:75,maxWidth:1600);if(x==null)return;setState(()=>file=File(x.path));widget.onChanged(file);}@override Widget build(BuildContext context)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[OutlinedButton.icon(onPressed:pick,icon:const Icon(Icons.add_a_photo_outlined),label:Text(file==null?'Attach photo (optional)':'Change photo')),if(file!=null)Image.file(file!,height:150),if(file!=null)TextButton(onPressed:(){setState(()=>file=null);widget.onChanged(null);},child:const Text('Remove photo'))]);}
